import{_ as t,o as e,c as o,aw as i}from"./chunks/framework.DLufY-ao.js";const d=JSON.parse('{"title":"Размеры и прокрутка элементов","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/js/js-web-api/dom/metrics.md","filePath":"wiki/dev-commit/js/js-web-api/dom/metrics.md"}'),s={name:"wiki/dev-commit/js/js-web-api/dom/metrics.md"};function a(n,l,r,c,p,h){return e(),o("div",null,[...l[0]||(l[0]=[i(`<h1 id="размеры-и-прокрутка-элементов" tabindex="-1">Размеры и прокрутка элементов <a class="header-anchor" href="#размеры-и-прокрутка-элементов" aria-label="Permalink to &quot;Размеры и прокрутка элементов&quot;">​</a></h1><h3 id="offset" tabindex="-1">offset <a class="header-anchor" href="#offset" aria-label="Permalink to &quot;offset&quot;">​</a></h3><ul><li>offsetParent - «родитель по дереву рендеринга» – ближайшая ячейка таблицы, body для статического позиционирования или ближайший позиционированный элемент для других типов позиционирования</li><li>offsetLeft/offsetTop - позиция в пикселях левого верхнего угла блока, относительно его offsetParent</li><li>offsetWidth/offsetHeight - «внешняя» ширина/высота блока, включая рамки</li></ul><hr><h3 id="client" tabindex="-1">client <a class="header-anchor" href="#client" aria-label="Permalink to &quot;client&quot;">​</a></h3><ul><li>clientLeft/clientTop - отступ области содержимого от левого-верхнего угла элемента. Если операционная система располагает вертикальную прокрутку справа, то равны ширинам левой/верхней рамки, если же слева (ОС на иврите, арабском), то clientLeft включает в себя прокрутку</li><li>clientWidth/clientHeight - ширина/высота содержимого вместе с полями padding, но без полосы прокрутки</li></ul><h3 id="scroll" tabindex="-1">scroll <a class="header-anchor" href="#scroll" aria-label="Permalink to &quot;scroll&quot;">​</a></h3><ul><li><p>scrollWidth/scrollHeight - ширина/высота содержимого, включая прокручиваемую область. Включает в себя padding и не включает полосы прокрутки</p></li><li><p>scrollLeft/scrollTop - ширина/высота прокрученной части документа, считается от верхнего левого угла</p></li><li><p><strong>Метрики</strong> - ряд свойств у элементов существует, содержащих их внешние и внутренние размеры</p></li><li><p>Метрики, в отличие от свойств CSS, содержат числа, всегда в пикселях и без единиц измерения на конце</p></li></ul><hr><hr><h2 id="offset-1" tabindex="-1">offset <a class="header-anchor" href="#offset-1" aria-label="Permalink to &quot;offset&quot;">​</a></h2><h3 id="offsetparent" tabindex="-1">offsetParent <a class="header-anchor" href="#offsetparent" aria-label="Permalink to &quot;offsetParent&quot;">​</a></h3><ul><li>В <strong>offsetParent</strong> находится ссылка на родительский элемент в смысле отображения на странице</li><li>Когда браузер рисует страницу, то он высчитывает дерево расположения элементов, иначе говоря «дерево геометрии» или «дерево рендеринга», которое содержит всю информацию о размерах</li><li>При этом одни элементы естественным образом рисуются внутри других. Но, к примеру, если у элемента стоит position:absolute, то его расположение вычисляется уже не относительно непосредственного родителя parentNode, а относительно ближайшего позиционированного элемента (т.е. свойство position которого не равно static), или BODY, если такой отсутствует</li><li>Получается, что элемент имеет в дополнение к обычному родителю в DOM – ещё одного «родителя по позиционированию», то есть относительно которого он рисуется. Этот элемент и будет в свойстве offsetParent</li></ul><h3 id="offsetleftиoffsettop" tabindex="-1">offsetLeftиoffsetTop <a class="header-anchor" href="#offsetleftиoffsettop" aria-label="Permalink to &quot;offsetLeftиoffsetTop&quot;">​</a></h3><ul><li><strong>offsetLeft/Top</strong> - свойства задают смещение относительно offsetParent</li><li>В примере внутренний <code>&lt;div&gt;</code> имеет DOM-родителя <code>&lt;form&gt;</code>, но offsetParent у него <code>&lt;main&gt;</code>, и сдвиги относительно его верхнего-левого угла будут в offsetLeft/Top:</li></ul><div class="language-html"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#383A42;">&lt;</span><span style="color:#E45649;">main</span><span style="color:#986801;"> style</span><span style="color:#383A42;">=</span><span style="color:#50A14F;">&quot;</span><span style="color:#383A42;">position: relative</span><span style="color:#50A14F;">&quot;</span><span style="color:#383A42;">&gt;</span></span>
<span class="line"><span style="color:#383A42;">	&lt;</span><span style="color:#E45649;">form</span><span style="color:#383A42;">&gt;</span></span>
<span class="line"><span style="color:#383A42;">		&lt;</span><span style="color:#E45649;">div</span><span style="color:#986801;"> id</span><span style="color:#383A42;">=</span><span style="color:#50A14F;">&quot;example&quot;</span><span style="color:#986801;"> style</span><span style="color:#383A42;">=</span><span style="color:#50A14F;">&quot;</span><span style="color:#383A42;">position: absolute; left: 180px; top: 180px</span><span style="color:#50A14F;">&quot;</span><span style="color:#383A42;">&gt;...&lt;/</span><span style="color:#E45649;">div</span><span style="color:#383A42;">&gt;</span></span>
<span class="line"><span style="color:#383A42;">	&lt;/</span><span style="color:#E45649;">form</span><span style="color:#383A42;">&gt;</span></span>
<span class="line"><span style="color:#383A42;">&lt;/</span><span style="color:#E45649;">main</span><span style="color:#383A42;">&gt;</span></span></code></pre></div><h3 id="offsetwidthиoffsetheight" tabindex="-1">offsetWidthиoffsetHeight <a class="header-anchor" href="#offsetwidthиoffsetheight" aria-label="Permalink to &quot;offsetWidthиoffsetHeight&quot;">​</a></h3><ul><li><p><strong>offsetWidth/Height</strong> - содержат «внешнюю» ширину/высоту элемента, то есть его полный размер, включая рамки border</p></li><li><p>offsetWidth = 390 - внешняя ширина блока, её можно получить сложением CSS-ширины (300px, но её часть на рисунке выше отнимает прокрутка, поэтому 284 + 16), полей(2<em>20px) и рамок (2</em>25px)</p></li><li><p>offsetHeight = 290 - внешняя высота блока</p></li><li><p>Координаты и размеры в JavaScript устанавливаются только для видимых элементов</p></li><li><p>Для элементов с display:none или находящихся вне документа дерево рендеринга не строится. Для них метрики равны нулю. offsetParent для таких элементов null</p></li></ul><hr><hr><h2 id="client-1" tabindex="-1">client <a class="header-anchor" href="#client-1" aria-label="Permalink to &quot;client&quot;">​</a></h2><h3 id="clientleftиclienttop" tabindex="-1">clientLeftиclientTop <a class="header-anchor" href="#clientleftиclienttop" aria-label="Permalink to &quot;clientLeftиclientTop&quot;">​</a></h3><ul><li><p><strong>clientLeft/Top</strong> - отступ внутренней части элемента от внешней. Обычно это только border, но если документ располагается справа налево (операционная система на арабском языке или иврите) полоса прокрутки в этом случае находится слева, и тогда свойство clientLeft включает в себя еще и ширину полосы прокрутки</p></li><li><p>clientLeft = 25 - ширина левой рамки</p></li><li><p>clientTop = 25 - ширина верхней рамки</p></li></ul><hr><ul><li>clientLeft = 41 - ширина левой рамки + полоса прокрутки</li><li>clientTop = 25 - ширина верхней рамки border</li></ul><h3 id="clientwidthclientheight" tabindex="-1">clientWidthclientHeight <a class="header-anchor" href="#clientwidthclientheight" aria-label="Permalink to &quot;clientWidthclientHeight&quot;">​</a></h3><ul><li><p><strong>clientWidth/Height</strong> - размер элемента внутри рамок border. Включают в себя ширину содержимого (не CSS-ширина) width вместе с полями padding, но без прокрутки</p></li><li><p>Если padding нет, то clientWidth/Height в точности равны размеру области содержимого, внутри рамок и полосы прокрутки</p></li><li><p>clientWidth = ШиринаСодержимого + Padding - Прокрутка</p></li></ul><hr><hr><h2 id="scroll-1" tabindex="-1">scroll <a class="header-anchor" href="#scroll-1" aria-label="Permalink to &quot;scroll&quot;">​</a></h2><h3 id="scrollwidthиscrollheight" tabindex="-1">scrollWidthиscrollHeight <a class="header-anchor" href="#scrollwidthиscrollheight" aria-label="Permalink to &quot;scrollWidthиscrollHeight&quot;">​</a></h3><ul><li><strong>scrollWidth/Height</strong> - аналоги clientWidth/clientHeight, но с учетом прокрутки</li><li>Свойства clientWidth/clientHeight относятся только к видимой области элемента, а scrollWidth/scrollHeight добавляют к ней прокрученную (которую не видно) по горизонтали/вертикали</li></ul><ul><li>scrollHeight = 723 - полная внутренняя высота, включая прокрученную область</li><li>scrollWidth = 324 - полная внутренняя ширина, в данном случае прокрутки нет, поэтому она равна clientWidth</li></ul><h3 id="scrollleftиscrolltop" tabindex="-1">scrollLeftиscrollTop <a class="header-anchor" href="#scrollleftиscrolltop" aria-label="Permalink to &quot;scrollLeftиscrollTop&quot;">​</a></h3><ul><li><strong>scrollLeft/Top</strong> - ширина/высота невидимой, прокрученной в данный момент, части элемента слева и сверху</li><li>Значения scrollLeft/scrollTop можно изменить, и браузер выполнит прокрутку элемента</li><li>element.scrollTop = 100</li></ul>`,35)])])}const u=t(s,[["render",a]]);export{d as __pageData,u as default};
